"  // --- One-Click Download ZIP Handler ---
  const downloadZipBtn = document.getElementById('btn-download-zip');
  if (downloadZipBtn) {
    downloadZipBtn.addEventListener('click', async () => {
      try {
        showToast('Packaging Smart City project into .ZIP...', 'cyan');
        const zip = new JSZip();

        // Fetch local files or package contents directly
        const fileNames = ['index.html', 'styles.css', 'app.js', 'README.md'];
        for (const name of fileNames) {
          try {
            const res = await fetch(name);
            if (res.ok) {
              const text = await res.text();
              zip.file(name, text);
            }
          } catch (e) {
            console.warn(`Could not fetch ${name} via fetch, skipping direct text fetch`, e);
          }
        }

        const content = await zip.generateAsync({ type: 'blob' });
        saveAs(content, 'smart-city-carpool.zip');
        showToast('smart-city-carpool.zip downloaded successfully!', 'emerald');
      } catch (err) {
        console.error('ZIP generation error:', err);
        showToast('Failed to create ZIP automatically. See README.md.', 'rose');
      }
    });
  }

  // Initial UI Render & Tilt Bind
  updateAllUI();
  bindTiltElements();
});"

