    j = json{
        {"id", s.id},
        {"name", s.name},
        {"x", s.x},
        {"y", s.y},
        {"z", s.z},
        {"zone", s.zone},
        {"icon", s.icon}
    };
}

inline void from_json(const json& j, Station& s) {
    j.at("id").get_to(s.id);
