.tab-view.active {
  display: block;
  opacity: 1;
  transform: translateY(0);
  /* FIX: Use animation since CSS transitions can't bridge display:none → block */
  animation: tabFadeIn 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
